@PluginDescriptor(
    name = "Lobbykin",
    description = "Lobbykin parties, Ready, reminders and raid start, death, exit and completion reports",
    tags = {"group", "party", "panel"}
)
public class LobbykinPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private OkHttpClient http;
    @Inject private Gson gson;
    @Inject private Notifier notifier;
    @Inject private ScheduledExecutorService executor;
    private BrowserPairing pairing;
    private volatile RaidTracker tracker;
    private NotificationPlanner notifications;
    private volatile SessionConnection connection;

    private volatile LobbykinPanel panel;
    private NavigationButton navigation;
    private String previousName;
    private int previousWorld = -1;

    @Override
    protected void startUp() throws Exception
    {
        notifications=new NotificationPlanner();
        pairing=new BrowserPairing(http,gson,executor,url->LinkBrowser.browse(url),text->{LobbykinPanel p=panel;if(p!=null)SwingUtilities.invokeLater(()->p.showPairing(text));},token->{SessionConnection c=connection;if(c!=null)c.connect(token);},text->{LobbykinPanel p=panel;if(p!=null)SwingUtilities.invokeLater(()->p.pairingFailed(text));});
        tracker=new RaidTracker(report->{SessionConnection c=connection;if(c!=null)c.report(report);},text->{
            LobbykinPanel p=panel;RaidTracker t=tracker;
            if(p!=null)SwingUtilities.invokeLater(()->{if(panel==p)p.showTrackingStatus(t==null?null:t.selectedGroup(),text,t!=null&&t.activeRun());});
        });
        onEdt(() -> {
            panel = new LobbykinPanel(() -> LinkBrowser.browse("https://lobbykin.com/"),
                () -> LinkBrowser.browse("https://lobbykin.com/runelite.html"),
                token -> { if(pairing!=null)pairing.cancel();SessionConnection c = connection; if (c != null) c.connect(token); }, () -> { SessionConnection c = connection; if(pairing!=null)pairing.cancel();if (c != null) c.disconnect(); },
                () -> refreshSessions(), id -> LinkBrowser.browse("https://lobbykin.com/?lobby=" + id),
                (id, ready) -> { SessionConnection c = connection; if (c != null) c.setReady(id, ready); });
            panel.configureV6((id,confirm)->{SessionConnection c=connection;if(c!=null)c.offerReply(id,confirm);},session->clientThread.invokeLater(()->{
                RaidTracker t=tracker;if(t==null)return;
                if(session.id.equals(t.selectedGroup()))t.stop(Instant.now());else t.arm(session.id,session.activity,insideRaid(session.activity),session.world,client.getWorld());
                refreshSessions();
            }));
            panel.configurePairCancel(()->{if(pairing!=null)pairing.cancel();});
            panel.configureBrowserConnection(()->{if(pairing!=null)pairing.start();});
            LobbykinPanel current = panel;
            connection = new SessionConnection(new SessionClient(http,gson), new SessionConnection.View()
            {
                private void show(Consumer<LobbykinPanel> action)
                {
                    SwingUtilities.invokeLater(() -> { if (panel == current) action.accept(current); });
                }
                public void connected(SessionSnapshot snapshot, Instant fetchedAt) {
                    for(String alert:notifications.accept(snapshot,fetchedAt))notifier.notify(alert);
                    clientThread.invokeLater(()->{RaidTracker t=tracker;if(t!=null&&t.selectedGroup()!=null){
                        SessionSnapshot.Session selected=snapshot.sessions.stream().filter(s->s.id.equals(t.selectedGroup())).findFirst().orElse(null);
                        if((selected!=null&&!selected.can_track)||(selected==null&&!t.keepActiveOnMissing(Instant.now())))t.stop(Instant.now());
                    }});
                    show(p -> p.showSessions(snapshot, fetchedAt));
                }
                public void disconnected(String message) { notifications.reset();clientThread.invokeLater(()->{RaidTracker t=tracker;if(t!=null)t.stop(Instant.now());});show(p -> p.showDisconnected(message)); }
                public void reportStatus(String group,String event,String state) {show(p->p.showReportStatus(group,event,state));}
                public void reportRejected(String group,String message) {clientThread.invokeLater(()->{RaidTracker t=tracker;if(t!=null&&group.equals(t.selectedGroup()))t.stop(Instant.now());});}
                public void error(String message) { show(p -> p.showError(message)); }
                public void loading() { show(LobbykinPanel::showLoading); }
            });
            navigation = NavigationButton.builder()
                .tooltip("Lobbykin")
                .icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
                .priority(8)
                .panel(panel)
                .build();
            toolbar.addNavigation(navigation);
        });
        clientThread.invokeLater(this::refreshPlayer);
    }

    @Override
    protected void shutDown() throws Exception
    {
        if(pairing!=null)pairing.cancel();pairing=null;
        RaidTracker tracking=tracker;if(tracking!=null)tracking.stop(Instant.now());tracker=null;
        SessionConnection active = connection;
        connection = null;
        if (active != null) active.disconnect();
        onEdt(() -> {
            if (navigation != null)
            {
                toolbar.removeNavigation(navigation);
            }
            if(panel!=null)panel.dispose();
            panel = null;
            navigation = null;
        });
        previousName = null;
        previousWorld = -1;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        refreshPlayer();
        RaidTracker t=tracker;Player local=client.getLocalPlayer();
        if(t!=null&&t.selectedRaid()!=null&&client.getGameState()==GameState.LOGGED_IN&&local!=null){
            String raid=t.selectedRaid();boolean inside=insideRaid(raid);int region=templateRegion();
            String diagnostic="Detector: "+raid+" · party="+("CoX".equals(raid)?0:client.getVarbitValue("ToB".equals(raid)?6440:14345))+" · instance="+client.isInInstancedRegion()+" · region="+region+" · in raid="+inside;
            String group=t.selectedGroup();LobbykinPanel p=panel;if(p!=null)SwingUtilities.invokeLater(()->{if(panel==p)p.showDetectorStatus(group,diagnostic);});
            t.observe(inside,!"ToA".equals(raid)||RaidPresence.toaStartRoom(region),local.getName(),client.getWorld(),Instant.now());
        }
    }

    private boolean insideRaid(String raid){
        if(client.getGameState()!=GameState.LOGGED_IN)return false;
        return RaidPresence.inside(raid,client.isInInstancedRegion(),
            "CoX".equals(raid)?0:client.getVarbitValue("ToB".equals(raid)?6440:14345),
            client.getVarbitValue(5432),client.getVarbitValue(5425),templateRegion());
    }

    private int templateRegion(){
        Player p=client.getLocalPlayer();if(p==null||p.getLocalLocation()==null)return -1;
        try{return WorldPoint.fromLocalInstance(client,p.getLocalLocation()).getRegionID();}catch(RuntimeException unavailable){return -1;}
    }

    @Subscribe
    public void onChatMessage(ChatMessage event){
        if(event.getType()!=ChatMessageType.GAMEMESSAGE&&event.getType()!=ChatMessageType.FRIENDSCHATNOTIFICATION)return;
        String text=Text.removeTags(event.getMessage());
        RaidTracker t=tracker;if(t!=null){Player local=client.getLocalPlayer();if(local!=null&&t.selectedRaid()!=null)t.context(local.getName(),client.getWorld(),"CoX".equals(t.selectedRaid())?client.getVarbitValue(5432)==1:insideRaid(t.selectedRaid()));t.gameMessage(text,Instant.now());}
    }

    @Subscribe
    public void onActorDeath(ActorDeath event){if(event.getActor()==client.getLocalPlayer()){RaidTracker t=tracker;if(t!=null)t.died(Instant.now(),"actor_death");}}

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if(event.getGameState()==GameState.CONNECTION_LOST||event.getGameState()==GameState.HOPPING||event.getGameState()==GameState.LOGIN_SCREEN){RaidTracker t=tracker;if(t!=null)t.interrupt("connection_lost",Instant.now());}
        refreshPlayer();
    }

    @Schedule(period = 30, unit = ChronoUnit.SECONDS, asynchronous = true)
    public void refreshSessions()
    {
        RaidTracker t=tracker;if(t!=null)t.heartbeat(Instant.now());
        SessionConnection active = connection;
        if (active != null) active.refresh();
    }

    private void refreshPlayer()
    {
        LobbykinPanel current = panel;
        if (current == null)
        {
            return;
        }
        Player local = client.getGameState() == GameState.LOGGED_IN ? client.getLocalPlayer() : null;
        String name = local == null ? null : local.getName();
        int world = name == null ? 0 : client.getWorld();
        if (java.util.Objects.equals(name, previousName) && world == previousWorld)
        {
            return;
        }
        previousName = name;
        previousWorld = world;
        SwingUtilities.invokeLater(() -> {
            if (panel == current)
            {
                current.showPlayer(name, world);
            }
        });
    }

    // RuneLite may already be on the EDT when starting/stopping a plugin.
    static void onEdt(Runnable action) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            action.run();
        }
        else
        {
            SwingUtilities.invokeAndWait(action);
        }
    }
}

package com.lobbykin;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Poll deltas only; initial inbox history is displayed without notification spam. */
final class NotificationPlanner
{
    private final Set<String> seen=new LinkedHashSet<>(),reminded=new LinkedHashSet<>();
    private boolean initialized;
    synchronized List<String> accept(SessionSnapshot snapshot,Instant now)
    {
        List<String> alerts=new ArrayList<>();
        if(snapshot.capabilities!=null&&snapshot.capabilities.notifications_read)
        {
            for(SessionSnapshot.Update update:snapshot.notifications)
            {
                boolean fresh=seen.add(update.id);
                if(initialized&&fresh&&update.read_at==null)alerts.add("Lobbykin: "+update.title);
            }
        }
        initialized=true;
        for(SessionSnapshot.Session session:snapshot.sessions)
        {
            if(!"host".equals(session.my_status)&&!"accepted".equals(session.my_status))continue;
            if(session.start_at==null)continue;
            try
            {
                Instant start=Instant.parse(session.start_at);long seconds=start.getEpochSecond()-now.getEpochSecond();
                if(seconds>0&&seconds<=900&&reminded.add(session.id+"|"+session.start_at))alerts.add("Lobbykin: "+session.title+" starts in "+((seconds+59)/60)+" min.");
            }
            catch(Exception ignored){ }
        }
        while(seen.size()>500)seen.remove(seen.iterator().next());
        while(reminded.size()>100)reminded.remove(reminded.iterator().next());
        return alerts;
    }
    synchronized void reset(){seen.clear();reminded.clear();initialized=false;}
}

package com.lobbykin;

/** Numeric client state + resolved instance-template regions. Never drives game input. */
final class RaidPresence
{
    private RaidPresence() {}
    // ToA Plugin Hub RaidRoom / RaidStateTracker and RuneLite Discord area mapping.
    // 13454 is the public lobby, NOT a raid. 14672 is the reward tomb (still inside).
    static boolean inside(String raid, boolean instance, int party, int coxDungeon, int coxState, int region)
    {
        if ("CoX".equals(raid)) return coxDungeon == 1 && coxState > 0;
        if ("ToA".equals(raid)) return toaRoom(region);
        return "ToB".equals(raid) && instance && (party == 2 || party == 3);
    }
    static boolean toaStartRoom(int region){return region!=14672&&toaRoom(region);}
    static boolean toaRoom(int region)
    {
        switch(region){
            case 14160: case 15698: case 15700: case 14162: case 14164:
            case 15186: case 15188: case 14674: case 14676: case 15184:
            case 15696: case 14672: return true;
            default:return false;
        }
    }
}

package com.lobbykin;

import com.google.gson.JsonObject;
import java.time.Duration;
import java.time.Instant;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Experimental observer. Never drives game input; only explicitly armed sessions. */
final class RaidTracker
{
    private static final Pattern PERSONAL_KC = Pattern.compile("^Your (?:completed |completion count for )(Theatre of Blood|Tombs of Amascut)(?::? (?:Entry|Story|Hard|Expert) Mode)? count is: [0-9,]+\\.?$");
    private static final Pattern TOTAL_TIME = Pattern.compile("^(Theatre of Blood|Tombs of Amascut)(?::? (?:Entry|Story|Hard|Expert) Mode)? total completion time: ([0-9]+(?::[0-9]{2}){1,2}(?:\\.[0-9]+)?).*");
    private static final Pattern COX_TIME = Pattern.compile(".*Duration: *([0-9]+(?::[0-9]{2}){1,2}(?:\\.[0-9]+)?).*", Pattern.CASE_INSENSITIVE);
    private final Consumer<JsonObject> reports;
    private final Consumer<String> status;
    private String group, raid, run, rsn;
    private Instant started,lastDeath;
    private String contextName;private int contextWorld;private boolean contextInside;
    private int world, leftTicks, outsideTicks;
    private Integer expectedWorld;
    private boolean waitForExit;

    RaidTracker(Consumer<JsonObject> reports, Consumer<String> status)
    {
        this.reports = reports;
        this.status = status;
    }

    synchronized boolean arm(String group, String raid, boolean alreadyInside)
    {
        if (!java.util.Arrays.asList("CoX", "ToB", "ToA").contains(raid)) return false;
        if (alreadyInside) { status.accept("Leave the current raid before arming a session."); return false; }
        stop(Instant.now());
        this.group=group; this.raid=raid; waitForExit=false;
        status.accept("Armed for " + raid + ". Enter the selected party's raid to start tracking.");
        return true;
    }

    synchronized boolean arm(String group,String raid,boolean alreadyInside,Integer expectedWorld,int currentWorld){
        if(expectedWorld!=null&&expectedWorld!=currentWorld){status.accept("Wrong world: hop to "+expectedWorld+" before tracking this session.");return false;}
        boolean armed=arm(group,raid,alreadyInside);if(armed)this.expectedWorld=expectedWorld;return armed;
    }
    synchronized boolean activeRun(){return run!=null;}
    synchronized boolean keepActiveOnMissing(Instant now){return run!=null&&started!=null&&now.isBefore(started.plusSeconds(21600));}
    synchronized void context(String name,int world,boolean inside){contextName=name;contextWorld=world;contextInside=inside;}
    synchronized String selectedGroup() { return group; }
    synchronized String selectedRaid() { return raid; }

    synchronized void observe(boolean inside,String player,int currentWorld,Instant now){observe(inside,inside,player,currentWorld,now);}
    synchronized void observe(boolean inside, boolean startEligible, String player, int currentWorld, Instant now)
    {
        context(player,currentWorld,inside);
        if (group == null) return;
        if (run != null && (!java.util.Objects.equals(player,rsn) || currentWorld != world))
        { interrupt("connection_lost",now); return; }
        if (run == null)
        {
            if (!inside) { if (++outsideTicks >= 5) waitForExit=false; return; }
            outsideTicks=0;
            if (waitForExit || player == null || !startEligible) return;
            if(expectedWorld!=null&&expectedWorld!=currentWorld){status.accept("Wrong world: hop to "+expectedWorld+" before entering the selected raid.");return;}
            start(now,"entry");
        }
        else if (inside) leftTicks=0;
        else if (++leftTicks >= 10) interrupt("left_raid",now);
    }

    synchronized void gameMessage(String text, Instant now)
    {
        if("CoX".equals(raid)&&text.equals("The raid has begun!")&&run==null&&!waitForExit&&contextInside&&contextName!=null){start(now,"game_message");return;}
        if(run==null)return;
        if(text.equals("Oh dear, you are dead!")||text.equals("You have died.")){died(now,"game_message");return;}
        if(text.equals("You have left the raid.")||text.equals("You leave the raid.")){interrupt("left_raid",now);return;}
        Integer duration=null;
        boolean completion=false;
        if ("CoX".equals(raid) && text.startsWith("Congratulations - your raid is complete!"))
        {
            completion=true;
            Matcher timer=COX_TIME.matcher(text);if(timer.matches())duration=parseDuration(timer.group(1));
        }
        else
        {
            Matcher total=TOTAL_TIME.matcher(text),kc=PERSONAL_KC.matcher(text);
            if (total.matches() && matchesRaid(total.group(1))) {completion=true;duration=parseDuration(total.group(2));}
            else if (kc.matches() && matchesRaid(kc.group(1))) completion=true;
        }
        if (!completion) return;
        String source=duration==null?"observed":"game_message";
        if(duration==null)duration=(int)Math.min(21600,Math.max(0,Duration.between(started,now).getSeconds()));
        reports.accept(report("completed","game_message",now,duration,source));
        run=null;waitForExit=true;outsideTicks=0;
        status.accept("Completion signal recorded · waiting for server confirmation. Session remains open.");
    }

    private void start(Instant now,String source){
        if(expectedWorld!=null&&expectedWorld!=contextWorld){status.accept("Wrong world: hop to "+expectedWorld+" before tracking this raid.");return;}
        run=UUID.randomUUID().toString();rsn=contextName;world=contextWorld;started=now;leftTicks=0;outsideTicks=0;lastDeath=null;
        reports.accept(report("started",source,now,null,"observed"));status.accept("Raid started · "+raid+("game_message".equals(source)?" · game message":" · entry observed"));
    }
    synchronized void died(Instant now,String source){
        if(run==null||(lastDeath!=null&&now.isBefore(lastDeath.plusSeconds(5))))return;
        lastDeath=now;reports.accept(report("died",source,now,null,"observed"));status.accept("Death recorded · the raid remains in progress.");
    }

    private boolean matchesRaid(String label)
    {
        return "ToB".equals(raid)&&label.equals("Theatre of Blood") || "ToA".equals(raid)&&label.equals("Tombs of Amascut");
    }

    synchronized void heartbeat(Instant now)
    {
        if(run!=null)reports.accept(report("heartbeat","heartbeat",now,null,"observed"));
    }

    synchronized void interrupt(String reason, Instant now)
    {
        if(run!=null)reports.accept(report("interrupted",reason,now,null,"observed"));
        run=null;waitForExit=true;outsideTicks=0;leftTicks=0;
        if(group!=null)status.accept("left_raid".equals(reason)?"Left raid · no completion recorded. Session remains open.":"Tracking interrupted · no completion inferred. Leave the raid before a new attempt.");
        if("connection_lost".equals(reason)){group=null;raid=null;status.accept("Tracking stopped after connection / character / world change. Leave the raid and select a session again.");}
    }

    synchronized void stop(Instant now)
    {
        if(run!=null)reports.accept(report("interrupted","manual_stop",now,null,"observed"));
        group=null;raid=null;run=null;expectedWorld=null;waitForExit=false;
        status.accept("Raid tracking: off.");
    }

    private JsonObject report(String event,String source,Instant now,Integer seconds,String durationSource)
    {
        JsonObject data=new JsonObject();data.addProperty("group_id",group);data.addProperty("client_run",run);
        data.addProperty("raid",raid);data.addProperty("event",event);data.addProperty("rsn",rsn);data.addProperty("world",world);
        data.addProperty("observed_at",now.toString());data.addProperty("duration_seconds",seconds);data.addProperty("duration_source",durationSource);data.addProperty("source",source);
        return data;
    }

    static Integer parseDuration(String value)
    {
        try
        {
            String[] parts=value.split(":");if(parts.length<2||parts.length>3)return null;
            double seconds=Double.parseDouble(parts[parts.length-1]);int minutes=Integer.parseInt(parts[parts.length-2]);
            if(seconds<0||seconds>=60||minutes<0||(parts.length==3&&minutes>=60))return null;
            double total=seconds+60*minutes+(parts.length==3?3600*Integer.parseInt(parts[0]):0);
            return total>=0&&total<=21600?(int)Math.round(total):null;
        }
        catch(NumberFormatException error){return null;}
    }
}

package com.lobbykin;

import java.io.IOException;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import java.util.UUID;
import okhttp3.MediaType;
import okhttp3.RequestBody;
import java.io.Reader;
import java.util.concurrent.TimeUnit;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/** No credentials are persisted or logged. Redirects are deliberately disabled. */
final class SessionClient
{
    private final OkHttpClient client;
    private final Gson gson;
    private final String url;

    SessionClient(OkHttpClient client, Gson gson)
    {
        this(client, gson, "https://lobbykin.com/api/runelite/sessions");
    }

    // Endpoint override is package-private for local tests, never a user setting.
    SessionClient(OkHttpClient client, Gson gson, String url)
    {
        this.client = client.newBuilder().followRedirects(false).followSslRedirects(false)
            .callTimeout(10, TimeUnit.SECONDS).build();
        this.url = url;
        this.gson = java.util.Objects.requireNonNull(gson);
    }

    interface Listener
    {
        void success(SessionSnapshot snapshot);
        void failure(boolean unauthorized, String message);
        default void rejected(String message) { failure(false, message); }
    }

    static boolean validToken(String token)
    {
        return token != null && token.matches("lk_rl_[0-9a-f]{64}");
    }

    Call read(String token, Listener listener)
    {
        return send(token, "sessions", null, listener);
    }

    Call setReady(String token, String group, boolean ready, Listener listener)
    {
        if (group == null || !UUID.fromString(group).toString().equals(group))
            throw new IllegalArgumentException("Invalid session.");
        JsonObject body = new JsonObject();
        body.addProperty("group_id", group);
        body.addProperty("ready", ready);
        return send(token, "ready", body.toString(), listener);
    }

    Call offerReply(String token,String group,boolean confirm,Listener listener)
    {
        UUID.fromString(group);JsonObject body=new JsonObject();body.addProperty("group_id",group);body.addProperty("confirm",confirm);
        return send(token,"offer",body.toString(),listener);
    }

    Call report(String token,JsonObject data,Listener listener)
    {
        return send(token,"event",data.toString(),listener);
    }

    private Call send(String token, String action, String body, Listener listener)
    {
        if (!validToken(token)) throw new IllegalArgumentException("Paste a valid Lobbykin access code.");
        boolean writing = body != null;
        String endpoint = writing ? url.substring(0, url.lastIndexOf('/') + 1) + action : url;
        Request.Builder builder = new Request.Builder().url(endpoint).header("Authorization", "Bearer " + token)
            .header("Accept", "application/json").header("User-Agent", "Lobbykin-RuneLite/0.9.4-rc1")
            .header("Cache-Control", "no-store");
        Request request = writing ? builder.post(RequestBody.create(MediaType.parse("application/json"), body)).build() : builder.get().build();
        Call call = client.newCall(request);
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call ignored, IOException error)
            {
                listener.failure(false, writing ? "Could not confirm the action. Refresh before retrying." : "Could not refresh. Check your connection and retry.");
            }

            @Override
            public void onResponse(Call ignored, Response response)
            {
                try (Response result = response)
                {
                    if (result.code() == 401 || (!writing && result.code() == 403))
                    {
                        listener.failure(true, "Access expired or revoked. Get a new code on Lobbykin.");
                        return;
                    }
                    if (writing && (result.code() == 403 || result.code() == 409))
                    {
                        listener.rejected(result.code() == 403 ? "Action denied. Check your permissions and accepted character." : "Action unavailable. Refresh sessions before retrying.");
                        return;
                    }
                    if (!result.isSuccessful() || result.body() == null)
                    {
                        listener.failure(false, writing ? "Could not confirm the action. Refresh before retrying." : "Lobbykin is temporarily unavailable. Retry shortly.");
                        return;
                    }
                    if (result.body().contentLength() > 131072)
                    {
                        throw new IOException("Response too large");
                    }
                    StringBuilder text = new StringBuilder();
                    try (Reader reader = result.body().charStream())
                    {
                        char[] buffer = new char[4096];
                        int count;
                        while ((count = reader.read(buffer)) != -1)
                        {
                            if (text.length() + count > 131072)
                            {
                                throw new IOException("Response too large");
                            }
                            text.append(buffer, 0, count);
                        }
                    }
                    listener.success(SessionSnapshot.parse(gson, text.toString()));
                }
                catch (Exception error)
                {
                    listener.failure(false, writing ? "Could not confirm the action. Refresh before retrying." : "Could not read sessions. Please retry.");
                }
            }
        });
        return call;
    }
}

package com.lobbykin;

import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import com.google.gson.JsonObject;
import okhttp3.Call;

/** Serial requests; stable report IDs survive transient failures in memory only. */
final class SessionConnection
{
    interface View {
        void connected(SessionSnapshot snapshot, Instant fetchedAt);
        void disconnected(String message);
        void error(String message);
        void loading();
        default void reportRejected(String group,String message) {}
        default void reportStatus(String group,String event,String state) {}
    }
    private final SessionClient client;
    private final View view;
    private String token;
    private long generation;
    private Call pending;
    private boolean busy;
    private SessionSnapshot snapshot;
    private final Deque<JsonObject> reports=new ArrayDeque<>();
    SessionConnection(SessionClient client,View view){this.client=client;this.view=view;}
    synchronized void connect(String candidate){
        disconnectInternal();
        if(!SessionClient.validToken(candidate)){view.disconnected("Paste the access code from lobbykin.com.");return;}
        token=candidate;view.disconnected("Connecting…");refresh();
    }
    synchronized void refresh(){
        if(token==null||busy)return;
        while(!reports.isEmpty()&&Instant.parse(reports.peek().get("observed_at").getAsString()).isBefore(Instant.now().minusSeconds(570)))reports.remove();
        request(reports.isEmpty()?"sessions":"event",reports.peek());
    }
    synchronized void setReady(String group,boolean ready){
        if(token==null||busy||snapshot==null||snapshot.sessions.stream().noneMatch(s->s.id.equals(group)&&s.can_set_ready))return;
        JsonObject body=new JsonObject();body.addProperty("group_id",group);body.addProperty("ready",ready);request("ready",body);
    }
    synchronized void offerReply(String group,boolean confirm){
        if(token==null||busy||snapshot==null||snapshot.sessions.stream().noneMatch(s->s.id.equals(group)&&s.can_reply_offer&&future(s.offer_until)))return;
        JsonObject body=new JsonObject();body.addProperty("group_id",group);body.addProperty("confirm",confirm);request("offer",body);
    }
    private static boolean future(String time){try{return Instant.parse(time).isAfter(Instant.now());}catch(Exception e){return false;}}
    synchronized void report(JsonObject body){
        if(token==null)return;
        boolean heartbeat="heartbeat".equals(body.get("event").getAsString());
        if(heartbeat&&(busy||!reports.isEmpty()))return;
        if(reports.size()>=64){view.error("Raid report queue is full. Stop tracking and reconnect.");return;}
        reports.add(body.deepCopy());view.reportStatus(body.get("group_id").getAsString(),body.get("event").getAsString(),"queued");if(!busy)refresh();
    }
    private void request(String action,JsonObject body){
        busy=true;long expected=generation;view.loading();
        SessionClient.Listener listener=new SessionClient.Listener(){
            public void success(SessionSnapshot data){synchronized(SessionConnection.this){
                if(expected!=generation)return;busy=false;pending=null;snapshot=data;
                if("event".equals(action)&&reports.peek()==body){reports.remove();view.reportStatus(body.get("group_id").getAsString(),body.get("event").getAsString(),"ACK · server confirmed");}
                view.connected(data,Instant.now());if(!reports.isEmpty())refresh();
            }}
            public void rejected(String message){synchronized(SessionConnection.this){
                if(expected!=generation)return;
                if("event".equals(action)){reports.removeIf(r->r.get("client_run").equals(body.get("client_run")));view.reportRejected(body.get("group_id").getAsString(),message);}
                busy=false;pending=null;snapshot=null;if("event".equals(action))view.reportStatus(body.get("group_id").getAsString(),body.get("event").getAsString(),"rejected · server denied");view.error(message);
            }}
            public void failure(boolean unauthorized,String message){synchronized(SessionConnection.this){
                if(expected!=generation)return;busy=false;pending=null;snapshot=null;
                if("event".equals(action))view.reportStatus(body.get("group_id").getAsString(),body.get("event").getAsString(),unauthorized?"rejected · access revoked":"error · retry queued");
                if(unauthorized){disconnectInternal();view.disconnected(message);}else view.error(message);
            }}
        };
        if("ready".equals(action))pending=client.setReady(token,body.get("group_id").getAsString(),body.get("ready").getAsBoolean(),listener);
        else if("offer".equals(action))pending=client.offerReply(token,body.get("group_id").getAsString(),body.get("confirm").getAsBoolean(),listener);
        else if("event".equals(action))pending=client.report(token,body,listener);
        else pending=client.read(token,listener);
    }
    synchronized void disconnect(){disconnectInternal();view.disconnected("Website account: not linked.");}
    private void disconnectInternal(){generation++;token=null;snapshot=null;busy=false;reports.clear();if(pending!=null)pending.cancel();pending=null;}
}

package com.lobbykin;

import com.google.gson.Gson;
import java.util.List;
import java.util.UUID;

/** Only the whitelisted, read-only session response, never a website session. */
final class SessionSnapshot
{
    String account;
    String scope;
    String expires_at;
    List<Session> sessions;
    Capabilities capabilities;
    List<Update> notifications = java.util.Collections.emptyList();

    static final class Capabilities { boolean ready_write, notifications_read, offers_write, tracking_write; }
    static final class Update { String id,group_id,kind,title,body,created_at,read_at; }
    static final class Member {String name,role;boolean ready;}
    static final class Participant {String name,state,end_reason,last_death_at;int deaths;}
    static final class Tracking { List<Participant> participants=java.util.Collections.emptyList(); int completed_runs; Integer deaths,failed_runs,interrupted_runs; List<Run> runs=java.util.Collections.emptyList(); String disclaimer; }
    static final class Run { String id,raid,status,started_at,completed_at,duration_source; int sequence,world,report_count; Integer duration_seconds; List<String> reporters=java.util.Collections.emptyList(); }

    static SessionSnapshot parse(Gson gson, String json)
    {
        SessionSnapshot result = gson.fromJson(json, SessionSnapshot.class);
        if (result == null || !"sessions:read".equals(result.scope)
            || result.account == null || result.account.length() > 120
            || result.sessions == null || result.sessions.size() > 30)
        {
            throw new IllegalArgumentException("Unexpected session response");
        }
        if(result.notifications==null)result.notifications=java.util.Collections.emptyList();
        if(result.notifications.size()>20)throw new IllegalArgumentException("Unexpected notifications");
        for(Update update:result.notifications)
        {
            if(update==null||update.id==null||update.title==null||update.title.length()>100||update.body==null||update.body.length()>300)throw new IllegalArgumentException("Unexpected notification");
            UUID.fromString(update.id);if(update.group_id!=null)UUID.fromString(update.group_id);
        }
        for (Session session : result.sessions)
        {
            if (session == null || session.id == null || !UUID.fromString(session.id).toString().equals(session.id)
                || session.title == null || session.title.length() > 200)
            {
                throw new IllegalArgumentException("Unexpected session response");
            }
            if(session.members==null)session.members=java.util.Collections.emptyList();
            if(session.members.size()>100)throw new IllegalArgumentException("Unexpected roster");
            for(Member m:session.members)if(m==null||m.name==null||m.name.length()>20)throw new IllegalArgumentException("Unexpected party member");
            if(session.tracking!=null){
                if((session.tracking.deaths!=null&&session.tracking.deaths<0)||(session.tracking.failed_runs!=null&&session.tracking.failed_runs<0)||(session.tracking.interrupted_runs!=null&&session.tracking.interrupted_runs<0))throw new IllegalArgumentException("Unexpected session totals");
                if(session.tracking.participants==null)session.tracking.participants=java.util.Collections.emptyList();
                if(session.tracking.participants.size()>100)throw new IllegalArgumentException("Unexpected participants");
                if(session.tracking.runs==null||session.tracking.runs.size()>5||session.tracking.completed_runs<0||session.tracking.completed_runs>200)throw new IllegalArgumentException("Unexpected tracking summary");
                for(Run run:session.tracking.runs)if(run==null||run.status==null||run.reporters==null||run.reporters.size()>10)throw new IllegalArgumentException("Unexpected run summary");
            }
        }
        return result;
    }

    static final class Session
    {
        String id;
        String title;
        String activity;
        String mode;
        String session_type;
        String start_at;
        String expires_at;
        Integer duration_minutes;
        Integer world;
        String meeting_point;
        String voice;
        String raid_phase,raid_lease_until;
        List<Member> members=java.util.Collections.emptyList();
        String my_status;
        String my_role;
        Boolean my_ready;
        boolean can_set_ready,can_reply_offer,can_track;
        String offer_until;
        Tracking tracking;
        Integer ready_count;
        Integer team_size;
    }
}

package com.lobbykin;
import java.awt.*;
/** Natural-height sidebar stack. Hidden disclosures occupy no space. */
final class VerticalStackLayout implements LayoutManager {
 private final int gap;
 VerticalStackLayout(int gap){this.gap=gap;}
 public void addLayoutComponent(String name,Component component){}
 public void removeLayoutComponent(Component component){}
 public Dimension minimumLayoutSize(Container parent){return preferredLayoutSize(parent);}
 public Dimension preferredLayoutSize(Container parent){synchronized(parent.getTreeLock()){
  Insets insets=parent.getInsets();int width=Math.max(1,(parent.getWidth()>0?parent.getWidth():205)-insets.left-insets.right),height=0,count=0;
  for(Component child:parent.getComponents())if(child.isVisible()){child.setSize(width,child.getHeight());height+=child.getPreferredSize().height;count++;}
  return new Dimension(width+insets.left+insets.right,height+Math.max(0,count-1)*gap+insets.top+insets.bottom);
 }}
 public void layoutContainer(Container parent){synchronized(parent.getTreeLock()){
  Insets insets=parent.getInsets();int width=Math.max(1,parent.getWidth()-insets.left-insets.right),y=insets.top;
  for(Component child:parent.getComponents())if(child.isVisible()){child.setSize(width,child.getHeight());int height=child.getPreferredSize().height;child.setBounds(insets.left,y,width,height);y+=height+gap;}
 }}
}

